//! aot_emit: Move bytecode to Zig source. One generated file per module; per function a state
//! machine (see aot_rt.zig) with a case per bytecode offset. The emitter decides nothing about
//! semantics: every instruction becomes `rt.exec` with the instruction as a compile-time
//! constant, calls and returns become `rt.slow`, and control flow becomes constant jumps.
const std = @import("std");
const move_format = @import("move_format");
const rt = @import("aot_rt.zig");

const ff = move_format.file_format;
const Allocator = std.mem.Allocator;

/// Which functions of a module to compile: a null `f` compiles every function with code.
pub const Select = struct {
    ctx: ?*const anyopaque = null,
    f: ?*const fn (ctx: ?*const anyopaque, addr: *const [32]u8, module: []const u8, func: []const u8) bool = null,

    pub fn wants(s: Select, addr: *const [32]u8, module: []const u8, func: []const u8) bool {
        const f = s.f orelse return true;
        return f(s.ctx, addr, module, func);
    }
};

/// Instructions that leave compiled code for the interpreter's `step` (frame switches).
fn leavesFrame(op: ff.Opcode) bool {
    return switch (op) {
        .Ret, .Call, .CallGeneric => true,
        else => false,
    };
}

fn printBytes(gpa: Allocator, out: *std.ArrayList(u8), b: []const u8) Allocator.Error!void {
    for (b, 0..) |x, i| try out.print(gpa, "{s}{d}", .{ if (i == 0) "" else ", ", x });
}

/// Appends the Zig source of module `cm` to `out`. Returns the number of functions emitted
/// (0 means nothing was selected and `out` is unchanged).
pub fn emitModule(gpa: Allocator, out: *std.ArrayList(u8), cm: *const ff.CompiledModule, sel: Select) Allocator.Error!u32 {
    const start = out.items.len;
    const digest = rt.digestModule(cm);
    const addr = cm.selfAddress();
    const mname = cm.selfName();
    try out.print(gpa,
        \\//! Generated by deepwave-aot from the bytecode of module {s} (digest {x}). Do not edit.
        \\const rt = @import("../aot_rt.zig");
        \\const Session = rt.Session;
        \\const Frame = rt.Frame;
        \\const Err = rt.StepError;
        \\
        \\
    , .{ mname, digest[0..8] });
    var n: u32 = 0;
    for (cm.function_defs, 0..) |fd, di| {
        const c = fd.code orelse continue;
        const fname = cm.identifiers[cm.function_handles[fd.function].name];
        if (!sel.wants(addr, mname, fname)) continue;
        try emitFunction(gpa, out, @intCast(di), c.code);
        n += 1;
    }
    if (n == 0) {
        out.shrinkRetainingCapacity(start);
        return 0;
    }
    try out.appendSlice(gpa, "pub const entry: rt.Entry = .{\n    .address = .{");
    try printBytes(gpa, out, addr);
    try out.print(gpa, "}},\n    .name = \"{s}\",\n    .digest = .{{", .{mname});
    try printBytes(gpa, out, &digest);
    try out.appendSlice(gpa, "},\n    .fns = &.{\n");
    for (cm.function_defs, 0..) |fd, di| {
        if (fd.code == null) continue;
        const fname = cm.identifiers[cm.function_handles[fd.function].name];
        if (!sel.wants(addr, mname, fname)) continue;
        try out.print(gpa, "        .{{ .def_idx = {d}, .name = \"{s}\", .run = fn_{d} }},\n", .{ di, fname, di });
    }
    try out.appendSlice(gpa, "    },\n};\n");
    return n;
}

fn emitFunction(gpa: Allocator, out: *std.ArrayList(u8), di: usize, code: []const ff.Instr) Allocator.Error!void {
    // the label is only legal when some case continues the switch
    var jumps = false;
    for (code) |ins| if (!leavesFrame(ins.op)) {
        jumps = true;
    };
    try out.print(gpa, "fn fn_{d}(s: *Session, f: *Frame) Err!bool {{\n    @setEvalBranchQuota(1 << 24); // every `continue` and inlined instruction body counts\n    {s}switch (f.pc) {{\n", .{ di, if (jumps) "sw: " else "" });
    for (code, 0..) |ins, pc| {
        try out.print(gpa, "        {d} => ", .{pc});
        if (leavesFrame(ins.op)) {
            try out.print(gpa, "return rt.slow(s, f, {d}),\n", .{pc});
            continue;
        }
        const call = try std.fmt.allocPrint(gpa, "rt.exec(s, f, .{{ .op = .{s}, .idx = {d}, .imm = {d} }}, {d})", .{ @tagName(ins.op), ins.idx, ins.imm, pc });
        defer gpa.free(call);
        switch (ins.op) {
            .Branch => try out.print(gpa, "{{\n            _ = try {s};\n            continue :sw {d};\n        }},\n", .{ call, ins.idx }),
            .BrTrue, .BrFalse => try out.print(gpa, "{{\n            if ((try {s}) == {d}) continue :sw {d} else continue :sw {d};\n        }},\n", .{ call, ins.idx, ins.idx, pc + 1 }),
            .VariantSwitch => try out.print(gpa, "continue :sw try {s},\n", .{call}),
            else => try out.print(gpa, "{{\n            _ = try {s};\n            continue :sw {d};\n        }},\n", .{ call, pc + 1 }),
        }
    }
    // a pc past the code (fall off the end, bad target) is the interpreter's PC_OVERFLOW
    try out.appendSlice(gpa, "        else => |pc| return rt.slow(s, f, pc),\n    }\n}\n\n");
}

/// The index file that registers the generated modules (`names`: file stems under aot_gen/).
pub fn emitIndex(gpa: Allocator, out: *std.ArrayList(u8), names: []const []const u8) Allocator.Error!void {
    try out.appendSlice(gpa,
        \\//! Generated by deepwave-aot: the compiled modules `aot.zig` matches loaded modules against.
        \\//! The checked-in default is empty (nothing compiled; the interpreter runs everything).
        \\const rt = @import("aot_rt.zig");
        \\
        \\pub const entries = [_]rt.Entry{
        \\
    );
    for (names) |n| try out.print(gpa, "    @import(\"aot_gen/{s}.zig\").entry,\n", .{n});
    try out.appendSlice(gpa, "};\n");
}

test "emit a small function: constant jumps, frame exits, stable digest" {
    const gpa = std.testing.allocator;
    const code = [_]ff.Instr{
        .{ .op = .LdU64, .imm = 7 },
        .{ .op = .LdU64, .imm = 5 },
        .{ .op = .Add },
        .{ .op = .BrTrue, .idx = 5 },
        .{ .op = .Branch, .idx = 0 },
        .{ .op = .Ret },
    };
    const sig0: []const ff.Token = &.{};
    const cm: ff.CompiledModule = .{
        .version = 7,
        .module_handles = &.{.{ .address = 0, .name = 0 }},
        .function_handles = &.{.{ .module = 0, .name = 1, .parameters = 0, .return_ = 0, .type_parameters = &.{} }},
        .signatures = &.{sig0},
        .identifiers = &.{ "m", "f" },
        .address_identifiers = &.{@as([32]u8, @splat(1))},
        .function_defs = &.{.{ .function = 0, .visibility = .Public, .is_entry = false, .acquires = &.{}, .code = .{ .locals = 0, .code = &code, .jump_tables = &.{} } }},
    };
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(gpa);
    try std.testing.expectEqual(@as(u32, 1), try emitModule(gpa, &out, &cm, .{}));
    const text = out.items;
    try std.testing.expect(std.mem.indexOf(u8, text, "fn fn_0(s: *Session, f: *Frame) Err!bool") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "2 => {\n            _ = try rt.exec(s, f, .{ .op = .Add, .idx = 0, .imm = 0 }, 2);\n            continue :sw 3;") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "if ((try rt.exec(s, f, .{ .op = .BrTrue, .idx = 5, .imm = 0 }, 3)) == 5) continue :sw 5 else continue :sw 4;") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "5 => return rt.slow(s, f, 5),") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, ".run = fn_0") != null);
    // the digest follows the code: one changed instruction changes it
    var code2 = code;
    code2[0].imm = 8;
    var cm2 = cm;
    cm2.function_defs = &.{.{ .function = 0, .visibility = .Public, .is_entry = false, .acquires = &.{}, .code = .{ .locals = 0, .code = &code2, .jump_tables = &.{} } }};
    try std.testing.expect(!std.mem.eql(u8, &rt.digestModule(&cm), &rt.digestModule(&cm2)));
    try std.testing.expectEqual(rt.digestModule(&cm), rt.digestModule(&cm));
    // nothing selected: nothing emitted
    out.clearRetainingCapacity();
    const none: Select = .{ .f = struct {
        fn f(_: ?*const anyopaque, _: *const [32]u8, _: []const u8, _: []const u8) bool {
            return false;
        }
    }.f };
    try std.testing.expectEqual(@as(u32, 0), try emitModule(gpa, &out, &cm, none));
    try std.testing.expectEqual(@as(usize, 0), out.items.len);
}
